package app.penmoss.engine.tree

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * `OrderKeys.keyBetween` against `packages/core/src/workspace/order.ts` (T40
 * P4, NT7): golden vectors generated by the TypeScript implementation, plus
 * betweenness on longer chains.
 */
class OrderKeysTest {
    private data class Vector(val before: String?, val after: String?, val key: String)

    // `vitest run test/golden-vec.test.ts --silent=false` over order.ts.
    private val golden = listOf(
        Vector(null, null, "a0"),
        Vector("a0", null, "a1"),
        Vector("a1", null, "a2"),
        Vector("a2", null, "a3"),
        Vector("a3", null, "a4"),
        Vector("a4", null, "a5"),
        Vector("a5", null, "a6"),
        Vector("a6", null, "a7"),
        Vector("a7", null, "a8"),
        Vector("a8", null, "a9"),
        Vector("a9", null, "aA"),
        Vector("aA", null, "aB"),
        Vector(null, null, "a0"),
        Vector(null, "a0", "Zz"),
        Vector(null, "Zz", "Zy"),
        Vector(null, "Zy", "Zx"),
        Vector(null, "Zx", "Zw"),
        Vector(null, "Zw", "Zv"),
        Vector(null, null, "a0"),
        Vector(null, "a0", "Zz"),
        Vector("a0", null, "a1"),
        Vector("a0", "a1", "a0V"),
        Vector("a0", "a0V", "a0G"),
        Vector("a0V", "a1", "a0l"),
        Vector("a0", "a0G", "a08"),
        Vector("Zz", "a0", "ZzV"),
        Vector("a0", "a2", "a1"),
        Vector("a0", "a1", "a0V"),
        Vector("a0V", "a1", "a0l"),
        Vector("a0l", "a1", "a0t"),
        Vector("a0t", "a1", "a0x"),
        Vector("a0x", "a1", "a0z"),
        Vector("a0z", "a1", "a0zV"),
        Vector("a0zV", "a1", "a0zl"),
        Vector("a0zl", "a1", "a0zt"),
    )

    @Test
    fun matchesTheTypeScriptImplementation() {
        for ((before, after, key) in golden) {
            assertEquals("keyBetween($before, $after)", key, OrderKeys.keyBetween(before, after))
        }
    }

    @Test
    fun everyKeyLandsBetweenItsBounds() {
        var lo: String? = null
        repeat(40) {
            val key = OrderKeys.keyBetween(lo, null)
            if (lo != null) assertTrue(key > lo!!)
            lo = key
        }
        var hi: String? = null
        repeat(40) {
            val key = OrderKeys.keyBetween(null, hi)
            if (hi != null) assertTrue(key < hi!!)
            hi = key
        }
        var a = "a0"
        var b = "a1"
        repeat(60) {
            val key = OrderKeys.keyBetween(a, b)
            assertTrue("$key between $a and $b", key > a && key < b)
            // Alternate sides so both bounds tighten.
            if (key.hashCode() % 2 == 0) a = key else b = key
        }
    }

    @Test
    fun refusesOutOfOrderBounds() {
        try {
            OrderKeys.keyBetween("a1", "a0")
            fail("expected out-of-order bounds to throw")
        } catch (expected: IllegalArgumentException) {
        }
    }
}
